use crate::{
    body::{boxed, Body, Empty, HttpBody},
    boxed::ErasedIntoRoute,
    response::Response,
};
use axum_core::response::IntoResponse;
use bytes::Bytes;
use http::{
    header::{self, CONTENT_LENGTH},
    HeaderMap, HeaderValue, Method, Request,
};
use super::method_routing::{AllowHeader, MethodEndpoint, MethodRouter};
use pin_project_lite::pin_project;
use std::{
    convert::Infallible,
    fmt,
    future::Future,
    pin::Pin,
    task::{Context, Poll},
};
use tower::{
    util::{BoxCloneService, MapResponseLayer, Oneshot},
    ServiceBuilder, ServiceExt,
};
use tower_layer::Layer;
use tower_service::Service;

/// How routes are stored inside a [`Router`](super::Router).
///
/// You normally shouldn't need to care about this type. It's used in
/// [`Router::layer`](super::Router::layer).
pub struct Route<B = Body, E = Infallible>(BoxCloneService<Request<B>, Response, E>);

impl<B, E> Route<B, E> {
    pub(crate) fn new<T>(svc: T) -> Self
    where
        T: Service<Request<B>, Error = E> + Clone + Send + 'static,
        T::Response: IntoResponse + 'static,
        T::Future: Send + 'static,
    {
        Self(BoxCloneService::new(
            svc.map_response(IntoResponse::into_response),
        ))
    }

    pub(crate) fn oneshot_inner(
        &mut self,
        req: Request<B>,
    ) -> Oneshot<BoxCloneService<Request<B>, Response, E>, Request<B>> {
        self.0.clone().oneshot(req)
    }

    pub(crate) fn layer<L, NewReqBody, NewError>(self, layer: L) -> Route<NewReqBody, NewError>
    where
        L: Layer<Route<B, E>> + Clone + Send + 'static,
        L::Service: Service<Request<NewReqBody>> + Clone + Send + 'static,
        <L::Service as Service<Request<NewReqBody>>>::Response: IntoResponse + 'static,
        <L::Service as Service<Request<NewReqBody>>>::Error: Into<NewError> + 'static,
        <L::Service as Service<Request<NewReqBody>>>::Future: Send + 'static,
        NewReqBody: 'static,
        NewError: 'static,
    {
        let layer = ServiceBuilder::new()
            .map_err(Into::into)
            .layer(MapResponseLayer::new(IntoResponse::into_response))
            .layer(layer)
            .into_inner();

        Route::new(layer.layer(self))
    }

    pub(crate) fn call_with_state<S>(
        &mut self,
        method_router: &mut MethodRouter<S, B, E>,
        req: Request<B>,
        state: S,
    ) -> RouteFuture<B, E>
    where
        B: HttpBody + Send + 'static,
        S: Clone,
    {
        let method = req.method().clone();
        let strip_body = method == Method::HEAD;

        if method == Method::HEAD {
            if method_router.head.is_some() {
                match &mut method_router.head {
                    MethodEndpoint::None => {}
                    MethodEndpoint::Route(route) => {
                        return RouteFuture::from_future(route.oneshot_inner(req))
                            .strip_body(strip_body);
                    }
                    MethodEndpoint::BoxedHandler(handler) => {
                        let mut route = handler.clone().0.into_route(state);
                        return RouteFuture::from_future(route.oneshot_inner(req))
                            .strip_body(strip_body);
                    }
                }
            } else if method_router.get.is_some() {
                match &mut method_router.get {
                    MethodEndpoint::None => {}
                    MethodEndpoint::Route(route) => {
                        return RouteFuture::from_future(route.oneshot_inner(req))
                            .strip_body(strip_body);
                    }
                    MethodEndpoint::BoxedHandler(handler) => {
                        let mut route = handler.clone().0.into_route(state);
                        return RouteFuture::from_future(route.oneshot_inner(req))
                            .strip_body(strip_body);
                    }
                }
            }
        } else if method == Method::GET {
            match &mut method_router.get {
                MethodEndpoint::None => {}
                MethodEndpoint::Route(route) => {
                    return RouteFuture::from_future(route.oneshot_inner(req)).strip_body(false);
                }
                MethodEndpoint::BoxedHandler(handler) => {
                    let mut route = handler.clone().0.into_route(state);
                    return RouteFuture::from_future(route.oneshot_inner(req)).strip_body(false);
                }
            }
        } else if method == Method::POST {
            match &mut method_router.post {
                MethodEndpoint::None => {}
                MethodEndpoint::Route(route) => {
                    return RouteFuture::from_future(route.oneshot_inner(req)).strip_body(false);
                }
                MethodEndpoint::BoxedHandler(handler) => {
                    let mut route = handler.clone().0.into_route(state);
                    return RouteFuture::from_future(route.oneshot_inner(req)).strip_body(false);
                }
            }
        } else if let Some(endpoint) = method_router.other_endpoint_mut(&method) {
            match endpoint {
                MethodEndpoint::None => {}
                MethodEndpoint::Route(route) => {
                    return RouteFuture::from_future(route.oneshot_inner(req)).strip_body(false);
                }
                MethodEndpoint::BoxedHandler(handler) => {
                    let mut route = handler.clone().0.into_route(state);
                    return RouteFuture::from_future(route.oneshot_inner(req)).strip_body(false);
                }
            }
        }

        let future = RouteFuture::from_future(self.0.clone().oneshot(req));
        future.with_allow_header(method_router.allow_header.clone())
    }
}

impl<B, E> Clone for Route<B, E> {
    fn clone(&self) -> Self {
        Self(self.0.clone())
    }
}

impl<B, E> fmt::Debug for Route<B, E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Route").finish()
    }
}

impl<B, E> Service<Request<B>> for Route<B, E>
where
    B: HttpBody,
{
    type Response = Response;
    type Error = E;
    type Future = RouteFuture<B, E>;

    #[inline]
    fn poll_ready(&mut self, _cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    #[inline]
    fn call(&mut self, req: Request<B>) -> Self::Future {
        RouteFuture::from_future(self.oneshot_inner(req))
    }
}

pin_project! {
    /// Response future for [`Route`].
    pub struct RouteFuture<B, E> {
        #[pin]
        kind: RouteFutureKind<B, E>,
        strip_body: bool,
        allow_header: Option<Bytes>,
    }
}

pin_project! {
    #[project = RouteFutureKindProj]
    enum RouteFutureKind<B, E> {
        Future {
            #[pin]
            future: Oneshot<
                BoxCloneService<Request<B>, Response, E>,
                Request<B>,
            >,
        },
        Response {
            response: Option<Response>,
        }
    }
}

impl<B, E> RouteFuture<B, E> {
    pub(crate) fn from_future(
        future: Oneshot<BoxCloneService<Request<B>, Response, E>, Request<B>>,
    ) -> Self {
        Self {
            kind: RouteFutureKind::Future { future },
            strip_body: false,
            allow_header: None,
        }
    }

    pub(crate) fn strip_body(mut self, strip_body: bool) -> Self {
        self.strip_body = strip_body;
        self
    }

    pub(crate) fn allow_header(mut self, allow_header: Bytes) -> Self {
        self.allow_header = Some(allow_header);
        self
    }

    pub(crate) fn with_allow_header(self, allow_header: AllowHeader) -> Self {
        match allow_header {
            AllowHeader::None => self.allow_header(Bytes::new()),
            AllowHeader::Skip => self,
            AllowHeader::Bytes(allow_header) => self.allow_header(allow_header.freeze()),
        }
    }
}

