    pub fn handle_error<F, T>(self, f: F) -> MethodRouter<S, B, Infallible>
    where
        F: Clone + Send + Sync + 'static,
        HandleError<Route<B, E>, F, T>: Service<Request<B>, Error = Infallible>,
        <HandleError<Route<B, E>, F, T> as Service<Request<B>>>::Future: Send,
        <HandleError<Route<B, E>, F, T> as Service<Request<B>>>::Response: IntoResponse + Send,
        T: 'static,
        E: 'static,
        B: 'static,
        S: 'static,
    {
        self.layer(HandleErrorLayer::new(f))
    }

    fn skip_allow_header(mut self) -> Self {
        self.allow_header = AllowHeader::Skip;
        self
    }

    pub(crate) fn fallback_route(&self, state: S) -> Route<B, E> {
        match &self.fallback {
            Fallback::Default(route) | Fallback::Service(route) => route.clone(),
            Fallback::BoxedHandler(handler) => handler.clone().into_route(state),
        }
    }

    pub(crate) fn other_endpoint_mut(
        &mut self,
        method: &Method,
    ) -> Option<&mut MethodEndpoint<S, B, E>> {
        if *method == Method::PUT {
            Some(&mut self.put)
        } else if *method == Method::PATCH {
            Some(&mut self.patch)
        } else if *method == Method::DELETE {
            Some(&mut self.delete)
        } else if *method == Method::OPTIONS {
            Some(&mut self.options)
        } else if *method == Method::TRACE {
            Some(&mut self.trace)
        } else {
            None
        }
    }
}

fn append_allow_header(allow_header: &mut AllowHeader, method: &'static str) {
