cd /data1/zhangyixiang/HuaWei/SWE-bench-FeatureEnvy-test/.tmp/opencode-swebench-tsy9c1t9/testbed && cat > axum/examples/fallback_state_check.rs <<'EOF'
use axum::{
    body::Body,
    extract::State,
    http::{Request, StatusCode},
    routing::get,
    Router,
};
use tower::ServiceExt;

#[tokio::main]
async fn main() {
    async fn fallback(State(state): State<&'static str>) -> &'static str {
        state
    }

    async fn not_found(State(_state): State<&'static str>) -> StatusCode {
        StatusCode::NOT_FOUND
    }

    let app = Router::new()
        .fallback(get(fallback).fallback(not_found))
        .with_state("foo");

    let res = app.clone().oneshot(Request::builder().uri("/").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);
    let body = axum::body::to_bytes(res.into_body(), usize::MAX).await.unwrap();
    assert_eq!(&body[..], b"foo");

    let res = app.oneshot(Request::builder().method("POST").uri("/").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(res.status(), StatusCode::NOT_FOUND);
}
EOF
